nts</strong><small>Use the fallback URL below when an attachment has no parent post.</small></span><input type="checkbox" name="redirect_orphan_attachments" value="1" <?php checked((int)seom_get('redirect_orphan_attachments',0),1); ?>></label></div><div class="seom-form-grid"><label>Orphan attachment redirect URL<input type="text" inputmode="url" name="orphan_attachment_url" value="<?php echo esc_attr(seom_get('orphan_attachment_url','')); ?>" placeholder="/  or  https://example.com/"><small>You can enter <code>/</code> to use the homepage.</small></label><label class="seom-toggle-row inline"><span><strong>Strip /category/ base</strong><small>Use carefully because category slugs can conflict with page slugs.</small></span><input type="checkbox" name="strip_category_base" value="1" <?php checked((int)seom_get('strip_category_base',0),1); ?>></label></div><h2>Webmaster Verification</h2><div class="seom-form-grid"><label>Google Search Console Verification ID<input name="google_verification" value="<?php echo esc_attr(seom_get('google_verification','')); ?>"></label><label>Bing Webmaster Verification ID<input name="bing_verification" value="<?php echo esc_attr(seom_get('bing_verification','')); ?>"></label><label>Yandex Verification ID<input name="yandex_verification" value="<?php echo esc_attr(seom_get('yandex_verification','')); ?>"></label><label>Baidu Verification ID<input name="baidu_verification" value="<?php echo esc_attr(seom_get('baidu_verification','')); ?>"></label><label>Google Analytics Measurement ID<input name="analytics_id" value="<?php echo esc_attr(seom_get('analytics_id','')); ?>" placeholder="G-XXXXXXXXXX"></label><label class="seom-toggle-row inline"><span><strong>Enable llms.txt</strong><small>Expose a small machine-readable content index at /llms.txt.</small></span><input type="checkbox" name="llms_enabled" value="1" <?php checked((int)seom_get('llms_enabled',0),1); ?>></label><label class="seom-full-label">Additional llms.txt notes<textarea name=